from pathlib import Path
import os
import sys


MISSIONS_ROOT = Path(
    os.environ.get(
        "MISSIONS_ROOT",
        str(Path.home() / "mission_data")
    )
)


if not MISSIONS_ROOT.exists():
    try:
        MISSIONS_ROOT.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        print(
            f"Warning: Could not create mission root folder: {MISSIONS_ROOT}\n{e}",
            file=sys.stderr
        )

from utils.logger import logger


class OCRService:
    def __init__(self):
        logger.info("Initializing PaddleOCR")

        try:
            from paddleocr import PaddleOCR

            self.ocr = PaddleOCR(
                use_angle_cls=True,
                lang="en",
                show_log=False,
            )

            logger.info("PaddleOCR initialized successfully")

        except Exception:
            logger.exception("Failed to initialize PaddleOCR")
            raise

    def extract_text(
        self,
        image_path,
    ):
        logger.info(
            f"Running OCR on: "
            f"{image_path}"
        )

        try:
            result = self.ocr.ocr(
                str(image_path),
                cls=True,
            )

            extracted_text = []

            if not result:
                logger.warning(
                    f"No OCR text found in "
                    f"{image_path}"
                )

                return ""

            for page in result:
                if not page:
                    continue

                for line in page:
                    try:
                        text = line[1][0]

                        extracted_text.append(
                            text
                        )

                    except Exception:
                        logger.warning(
                            "Failed to parse "
                            "OCR line"
                        )

            final_text = "\n".join(
                extracted_text
            )

            logger.info(
                f"OCR extraction complete. "
                f"Extracted "
                f"{len(extracted_text)} "
                f"text blocks."
            )

            return final_text

        except Exception:
            logger.exception(
                f"OCR extraction failed "
                f"for {image_path}"
            )

            raise

